B.TE=new A.bx("bld_steam_vent",B.aw,"Volkanik Buhar Menfezi (Termal Bas\u0131n\xe7)","Volcanic Steam Vent (Thermal Pressure)","Yanarda\u011f \xe7atlaklar\u0131ndan y\xfcksek bas\u0131n\xe7l\u0131 buhar toplar; kom\u015fu ocaklar\u0131n \xfcretimini h\u0131zland\u0131r\u0131r.","Harnesses high-pressure steam from volcanic fissures to supercharge smelters.","Buhar Menfezi, Yanarda\u011f karolar\u0131na kurulur. Saniyede 0.28 buhar g\xfcc\xfc \xfcretir. \xc7evresindeki maden ve d\xf6k\xfcmhanelere bas\u0131n\xe7 aktararak demir ve \xe7elik \xfcretim h\u0131z\u0131n\u0131 %50 art\u0131r\u0131r.","Generates 0.28 Steam/sec on Volcano tiles, boosting neighboring forge speeds by 50%.",B.wc,B.fs,"SV.40 | VOLKAN",B.a5M,B.K,B.K,B.YH,B.Zo,B.YK)
B.a6L={"A\xe7\u0131l\u0131\u015f Seviyesi":0,"Etki Menzili":1,"Sald\u0131r\u0131 T\xfcr\xfc":2,"At\u0131\u015f S\u0131kl\u0131\u011f\u0131":3}
